<?php
defined('WB_PATH')or die('No direct access');
$core=WB_PATH.'/modules/mailer/src/MailerRegistry.php';if(is_file($core))require_once $core;if(!class_exists('WbceMailerRegistry')||!function_exists('wbce_add_filter'))return;
wbce_add_filter('mailer.providers',static function($providers){$providers['symfony']=['name'=>'Symfony Mailer','description'=>'Standardtransport über SMTP, Sendmail und DSN.','module'=>'mailer_symfony','send'=>static function($message,$settings){$provider=(string)($settings['selected_provider']??'smtp');$dsn=(string)Settings::get('mailer_'.$provider.'_dsn','');if($dsn==='')$dsn=$provider==='smtp'?'smtp://localhost':' ';if(trim($dsn)==='')return ['handled'=>false];$autoload=WB_PATH.'/include/SymfonyMailer/vendor/autoload.php';if(!is_file($autoload))return ['handled'=>true,'sent'=>false,'error'=>'Symfony Mailer ist nicht installiert.','provider'=>'symfony'];require_once $autoload;try{$transport=\Symfony\Component\Mailer\Transport::fromDsn($dsn);$mailer=new \Symfony\Component\Mailer\Mailer($transport);$email=(new \Symfony\Component\Mime\Email())->subject((string)($message['subject']??''))->html((string)($message['html']??''))->text((string)($message['text']??''));$source=$message['mailer']??null;$from=(string)($settings['from_email']??'');if($from!==''&&filter_var($from,FILTER_VALIDATE_EMAIL))$email->from($from);elseif(is_object($source)&&property_exists($source,'From')&&!empty($source->From))$email->from((string)$source->From);if(is_object($source)&&property_exists($source,'to'))foreach((array)$source->getToAddresses() as $address)$email->to($address[0]);$mailer->send($email);return ['handled'=>true,'sent'=>true,'provider'=>'symfony'];}catch(\Throwable $e){return ['handled'=>true,'sent'=>false,'error'=>$e->getMessage(),'provider'=>'symfony'];}}];return $providers;});
